def eval_rpn(tokens):
    stack = []

    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()

            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                # Truncate toward zero (not floor division)
                result = int(a / b)
                stack.append(result)
        else:
            stack.append(int(token))

    return stack[0]
