def min_edit_distance(a: str, b: str) -> int:
    m, n = len(a), len(b)

    # dp[i][j] holds the edit distance between a[:i] and b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases: transforming to/from an empty string
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                # Characters match: no extra cost
                dp[i][j] = dp[i - 1][j - 1]
            else:
                # Cost of deletion, insertion, or substitution (all = 1)
                dp[i][j] = 1 + min(
                    dp[i - 1][j],      # deletion
                    dp[i][j - 1],      # insertion
                    dp[i - 1][j - 1]   # substitution
                )

    return dp[m][n]
