<body>

<div id="info">🖱️ Drag to orbit &nbsp;|&nbsp; Scroll to zoom &nbsp;|&nbsp; Right-drag to pan</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js"></script>

<script>
(function () {
  // ── Scene, Camera, Renderer ────────────────────────────────
  const scene = new THREE.Scene();
  scene.fog = new THREE.FogExp2(0x0a0a1a, 0.035);

  const camera = new THREE.PerspectiveCamera(60, innerWidth / innerHeight, 0.1, 200);
  camera.position.set(4, 3, 6);

  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(innerWidth, innerHeight);
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.2;
  document.body.appendChild(renderer.domElement);

  // ── Controls ───────────────────────────────────────────────
  const controls = new THREE.OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.06;
  controls.minDistance = 2;
  controls.maxDistance = 30;

  // ── Lighting ───────────────────────────────────────────────
  const ambientLight = new THREE.AmbientLight(0x404060, 0.5);
  scene.add(ambientLight);

  const dirLight = new THREE.DirectionalLight(0xffffff, 1.0);
  dirLight.position.set(8, 12, 6);
  dirLight.castShadow = true;
  dirLight.shadow.mapSize.set(1024, 1024);
  scene.add(dirLight);

  const pointLight1 = new THREE.PointLight(0xff6030, 1.5, 20);
  pointLight1.position.set(-4, 3, 2);
  scene.add(pointLight1);

  const pointLight2 = new THREE.PointLight(0x3080ff, 1.5, 20);
  pointLight2.position.set(4, -1, -3);
  scene.add(pointLight2);

  // ── Main Torus Knot ────────────────────────────────────────
  const torusKnotGeo = new THREE.TorusKnotGeometry(1.5, 0.45, 128, 32);
  const torusKnotMat = new THREE.MeshStandardMaterial({
    color: 0xcc44ff,
    metalness: 0.6,
    roughness: 0.25,
    emissive: 0x220033,
  });
  const torusKnot = new THREE.Mesh(torusKnotGeo, torusKnotMat);
  torusKnot.castShadow = true;
  scene.add(torusKnot);

  // ── Orbiting Spheres ───────────────────────────────────────
  const spheres = [];
  const sphereColors = [0xff3366, 0x33ff99, 0xffcc33, 0x33ccff, 0xff6633];
  for (let i = 0; i < 5; i++) {
    const geo = new THREE.SphereGeometry(0.18 + Math.random() * 0.12, 24, 24);
    const mat = new THREE.MeshStandardMaterial({
      color: sphereColors[i],
      metalness: 0.8,
      roughness: 0.2,
      emissive: sphereColors[i],
      emissiveIntensity: 0.3,
    });
    const mesh = new THREE.Mesh(geo, mat);
    scene.add(mesh);
    spheres.push({
      mesh,
      radius: 2.8 + Math.random() * 1.5,
      speed: 0.4 + Math.random() * 0.6,
      offset: (i / 5) * Math.PI * 2,
      tilt: (Math.random() - 0.5) * 1.2,
    });
  }

  // ── Particle Ring ──────────────────────────────────────────
  const particleCount = 600;
  const positions = new Float32Array(particleCount * 3);
  const pColors = new Float32Array(particleCount * 3);
  for (let i = 0; i < particleCount; i++) {
    const angle = Math.random() * Math.PI * 2;
    const r = 3.5 + Math.random() * 4;
    positions[i * 3]     = Math.cos(angle) * r;
    positions[i * 3 + 1] = (Math.random() - 0.5) * 1.5;
    positions[i * 3 + 2] = Math.sin(angle) * r;
    const c = new THREE.Color().setHSL(0.7 + Math.random() * 0.3, 0.8, 0.6);
    pColors[i * 3]     = c.r;
    pColors[i * 3 + 1] = c.g;
    pColors[i * 3 + 2] = c.b;
  }
  const particleGeo = new THREE.BufferGeometry();
  particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  particleGeo.setAttribute('color', new THREE.BufferAttribute(pColors, 3));
  const particleMat = new THREE.PointsMaterial({
    size: 0.06,
    vertexColors: true,
    transparent: true,
    opacity: 0.8,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const particles = new THREE.Points(particleGeo, particleMat);
  scene.add(particles);

  // ── Ground Plane (shadow receiver) ────────────────────────
  const groundGeo = new THREE.PlaneGeometry(40, 40);
  const groundMat = new THREE.MeshStandardMaterial({
    color: 0x111122,
    metalness: 0.3,
    roughness: 0.8,
  });
  const ground = new THREE.Mesh(groundGeo, groundMat);
  ground.rotation.x = -Math.PI / 2;
  ground.position.y = -2.5;
  ground.receiveShadow = true;
  scene.add(ground);

  // ── Mouse interaction: color shift on hover ────────────────
  let targetHue = 0.78;
  const mouse = new THREE.Vector2();
  window.addEventListener('mousemove', (e) => {
    mouse.x = (e.clientX / innerWidth) * 2 - 1;
    mouse.y = -(e.clientY / innerHeight) * 2 + 1;
    targetHue = ((mouse.x + 1) * 0.5 + performance.now() * 0.00003) % 1;
  });

  // ── Animation Loop ────────────────────────────────────────
  const clock = new THREE.Clock();

  function animate() {
    requestAnimationFrame(animate);
    const t = clock.getElapsedTime();

    // Rotate main object
    torusKnot.rotation.x = t * 0.3;
    torusKnot.rotation.y = t * 0.5;

    // Hue shift based on mouse
    torusKnotMat.color.setHSL(targetHue, 0.7, 0.5);
    torusKnotMat.emissive.setHSL((targetHue + 0.1) % 1, 0.6, 0.12);

    // Orbiting spheres
    for (const s of spheres) {
      const a = t * s.speed + s.offset;
      s.mesh.position.x = Math.cos(a) * s.radius;
      s.mesh.position.z = Math.sin(a) * s.radius;
      s.mesh.position.y = Math.sin(a * 0.7 + s.tilt) * 1.2 + Math.sin(t * 0.5) * 0.3;
    }

    // Animate lights
    pointLight1.position.x = Math.sin(t * 0.8) * 5;
    pointLight1.position.z = Math.cos(t * 0.8) * 5;
    pointLight2.position.x = Math.cos(t * 0.6) * 4;
    pointLight2.position.z = Math.sin(t * 0.6) * 4;

    // Rotate particles slowly
    particles.rotation.y = t * 0.05;

    controls.update();
    renderer.render(scene, camera);
  }

  animate();

  // ── Resize ────────────────────────────────────────────────
  window.addEventListener('resize', () => {
    camera.aspect = innerWidth / innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(innerWidth, innerHeight);
  });
})();
</script>

</body>
</html>
